// Command v4formatgen generates the Go and C constants shared by the V4
// container and native engine. Generated files are committed so normal builds
// do not require this command.
package main

import (
	"encoding/json"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type definition struct {
	FormatVersion        int            `json:"format_version"`
	PrefixSize           int            `json:"prefix_size"`
	FooterSize           int            `json:"footer_size"`
	WindowDescriptorSize int            `json:"window_descriptor_size"`
	IdentityChunkSize    int            `json:"identity_chunk_size"`
	WindowKinds          map[string]int `json:"window_kinds"`
	Codecs               map[string]int `json:"codecs"`
	Opcodes              map[string]int `json:"opcodes"`
}

func main() {
	root := "."
	payload, err := os.ReadFile(filepath.Join(root, "v4_format.def"))
	if err != nil {
		panic(err)
	}
	var def definition
	if err := json.Unmarshal(payload, &def); err != nil {
		panic(err)
	}
	generatedGo, err := format.Source([]byte(generateGo(def)))
	if err != nil {
		panic(err)
	}
	if err := os.WriteFile(filepath.Join(root, "zz_v4_generated.go"), generatedGo, 0o644); err != nil {
		panic(err)
	}
	if err := os.WriteFile(filepath.Join(root, "..", "nativev4", "v4_format_generated.h"), []byte(generateC(def)), 0o644); err != nil {
		panic(err)
	}
}

func names(values map[string]int) []string {
	result := make([]string, 0, len(values))
	for name := range values {
		result = append(result, name)
	}
	sort.Strings(result)
	return result
}

func exported(name string) string {
	parts := strings.Split(name, "_")
	for i := range parts {
		if parts[i] == "" {
			continue
		}
		parts[i] = strings.ToUpper(parts[i][:1]) + parts[i][1:]
	}
	return strings.Join(parts, "")
}

func macro(name string) string { return strings.ToUpper(name) }

func generateGo(def definition) string {
	var b strings.Builder
	b.WriteString("// Code generated by internal/patchformat/gen; DO NOT EDIT.\n\npackage patchformat\n\nconst (\n")
	fmt.Fprintf(&b, "\tFormatVersion = %d\n\tPrefixSize = %d\n\tFooterSize = %d\n\tWindowDescriptorSize = %d\n\tIdentityChunkSize uint64 = %d\n", def.FormatVersion, def.PrefixSize, def.FooterSize, def.WindowDescriptorSize, def.IdentityChunkSize)
	for _, name := range names(def.WindowKinds) {
		fmt.Fprintf(&b, "\tWindow%s WindowKind = %d\n", exported(name), def.WindowKinds[name])
	}
	for _, name := range names(def.Codecs) {
		fmt.Fprintf(&b, "\tCodec%s Codec = %d\n", exported(name), def.Codecs[name])
	}
	for _, name := range names(def.Opcodes) {
		fmt.Fprintf(&b, "\tOpcode%s byte = %d\n", exported(name), def.Opcodes[name])
	}
	b.WriteString(")\n")
	return b.String()
}

func generateC(def definition) string {
	var b strings.Builder
	b.WriteString("/* Code generated by internal/patchformat/gen; DO NOT EDIT. */\n#ifndef VIPR_V4_FORMAT_GENERATED_H\n#define VIPR_V4_FORMAT_GENERATED_H\n")
	fmt.Fprintf(&b, "#define VIPR_V4_FORMAT_VERSION %dU\n#define VIPR_V4_PREFIX_SIZE %dU\n#define VIPR_V4_FOOTER_SIZE %dU\n#define VIPR_V4_WINDOW_DESCRIPTOR_SIZE %dU\n#define VIPR_V4_IDENTITY_CHUNK_SIZE %dULL\n", def.FormatVersion, def.PrefixSize, def.FooterSize, def.WindowDescriptorSize, def.IdentityChunkSize)
	for _, name := range names(def.WindowKinds) {
		fmt.Fprintf(&b, "#define VIPR_WINDOW_%s %dU\n", macro(name), def.WindowKinds[name])
	}
	for _, name := range names(def.Codecs) {
		fmt.Fprintf(&b, "#define VIPR_CODEC_%s %dU\n", macro(name), def.Codecs[name])
	}
	for _, name := range names(def.Opcodes) {
		fmt.Fprintf(&b, "#define VIPR_OPCODE_%s %dU\n", macro(name), def.Opcodes[name])
	}
	b.WriteString("#endif\n")
	return b.String()
}
